  const foot=`<footer class="footer"><div class="footer-brand">HEATSHIELD <span>·</span> THANE, MAHARASHTRA</div><p>A field atlas for understanding heat, place and shade.</p><span>Live weather context · Sample-area estimates are illustrative</span></footer></div>`;
